async function newPage(viewport={width:1440,height:900}){resetMock();const context=await browser.newContext({viewport,serviceWorkers:'block',acceptDownloads:true});const page=await context.newPage();currentPage=page;page.setDefaultTimeout(15000);page.on('pageerror',error=>evidence.pageErrors.push({message:error.message,stack:error.stack}));page.on('console',message=>{if(message.type()==='error')evidence.consoleErrors.push(message.text())});page.on('response',response=>{const u=new URL(response.url());if(u.origin===origin&&u.pathname.startsWith('/api/'))evidence.network.push({method:response.request().method(),path:u.pathname,query:u.search,status:response.status()})});await page.route('**/*',async route=>{if(new URL(route.request().url()).origin===origin)await route.continue();else{evidence.unverified.push({kind:'external-navigation-blocked',url:route.request().url()});await route.abort()}});await page.goto(origin,{waitUntil:'load'});await settle(page);const home=await page.evaluate(()=>({view:App.ui.view,rows:[...document.querySelectorAll('.portfolio-table tbody tr')].map(row=>row.cells[0]?.textContent.trim()),flags:App.state.projects.map(p=>({id:p.id,isExample:p.isExample,sample:p.sample}))}));assert.equal(home.view,'portfolio');assert.deepEqual(home.rows.slice().sort(),['A','B','C']);evidence.fixture.homeChecks??=[];evidence.fixture.homeChecks.push({viewport,...home,status:'three-approved-sample-rows-visible'});return {context,page}}
async function clickControl(page,action,data={},scope='body'){const locator=page.locator(scope+' [data-action="'+action+'"]'),candidates=await locator.count();for(let i=0;i<candidates;i++){const item=locator.nth(i),matches=await item.evaluate((node,data)=>Object.entries(data).every(([key,value])=>String(node.dataset[key])===String(value)),data);if(matches&&await item.isVisible()){await item.click();return}}throw Error('보이는 버튼을 찾지 못했습니다: '+action+' '+JSON.stringify(data))}
async function closeDialog(page){const seen=new Set();while(await page.locator('#app-dialog').isVisible()){const before=await page.locator('#app-dialog').innerText(),key=sha(before);if(seen.has(key))throw Error('팝업 닫기 반복 또는 닫기 불가: '+before.slice(0,100));seen.add(key);const discard=page.locator('#app-dialog [data-action="draft-close"],#app-dialog [data-action="draft-discard"]');if(await discard.count())await discard.first().click();else await page.keyboard.press('Escape');await page.waitForTimeout(25);if(await page.locator('#app-dialog').isVisible()&&(await page.locator('#app-dialog').innerText())===before){const close=page.locator('#app-dialog [data-action="modal-close"]');if(await close.count())await close.click();else break}}if(await page.locator('#app-dialog').isVisible())throw Error('팝업 닫기 불가')}
async function navigate(page,view,tab=''){await closeDialog(page);await clickControl(page,'go',{view},'#sidebar');await settle(page);await settledUI(page);if(tab){await clickControl(page,'tab',{view,tab},'#content');await settle(page);await settledUI(page)}return page.evaluate(()=>({view:App.ui.view,tab:App.ui.tabs[App.ui.view]||'',projectId:App.ui.projectId}))}
async function inspectMenus(page,viewport){const mains=await page.locator('#sidebar [data-action="go"]').evaluateAll(nodes=>nodes.map(n=>({view:n.dataset.view,label:n.innerText.trim()})));for(const main of mains){await navigate(page,main.view);const sub=await page.locator('#content [data-action="tab"]').evaluateAll(nodes=>nodes.map(n=>({tab:n.dataset.tab,label:n.innerText.trim()})));const tabs=sub.length?sub:[{tab:'',label:'단일 화면'}];for(const item of tabs){const context=await navigate(page,main.view,item.tab),rows=await controls(page,context);const overflow=await page.evaluate(()=>({page:document.documentElement.scrollWidth>innerWidth+1,content:document.getElementById('content').scrollWidth,view:App.ui.view}));evidence.checks.push({kind:'menu-render',viewport,context,visibleControls:rows.length,overflow,status:'rendered-not-functional-acceptance'});if(main.view==='permit'&&item.tab==='permits'||main.view==='spec'&&item.tab==='overview'||main.view==='cost'&&item.tab==='detail')await capture(page,viewport.width+'-'+main.view+'-'+item.tab);console.log('MENU '+viewport.width+' '+main.view+'/'+item.tab+' controls='+rows.length)}}}
async function runFlow(name,fn,viewport={width:1440,height:900}){const {context,page}=await newPage(viewport),flow={name,viewport,status:'running',steps:[],networkStart:evidence.network.length};evidence.flows.push(flow);try{await fn(page,flow);flow.status='validated-mocked-UI-flow';console.log('FLOW PASS '+name)}catch(error){flow.status='failed';flow.error=error.message;flow.stack=error.stack;flow.context=await page.evaluate(()=>({view:App.ui.view,tab:App.ui.tabs[App.ui.view],projectId:App.ui.projectId,popup:document.querySelector('#app-dialog h2')?.textContent,body:document.querySelector('#app-dialog .dialog-body')?.innerText.slice(0,14000),formError:document.getElementById('form-error')?.textContent,fields:[...document.querySelectorAll('#app-dialog input,#app-dialog select,#app-dialog textarea')].filter(n=>n.type!=='password').map(n=>({name:n.name,type:n.type,value:n.value,required:n.required})),toast:document.getElementById('toast')?.innerText})).catch(()=>null);evidence.defects.push({name,error:error.message,context:flow.context});await capture(page,'failure-'+name);console.log('FLOW FAIL '+name+' '+error.message)}finally{flow.networkEnd=evidence.network.length;await context.close()}}
