const stableData=data=>Object.fromEntries(Object.entries(data||{}).filter(([key])=>!['action','id','project','projectId','tip','index','inlineValue','inlineId','inlineProject'].includes(key)).map(([key,value])=>[key,String(value).replace(/[a-f0-9]{8}-[a-f0-9-]{27,}/gi,'{id}')]));
const controlKey=control=>{const data=stableData(control.data);if(control.action.startsWith('cbs-catalog-')){if(data.key)data.key=data.key.split(':')[0]+':{type}';for(const name of ['group','catalogToggle'])if(data[name])data[name]=data[name].split(':')[0]+':{group}';}return control.action+'|'+JSON.stringify(data)+'|'+(control.action==='DETAILS_TOGGLE'?control.label:'');};
